<script module lang="ts">
/**
 * Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotOutlet, SlotScope, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export interface AvatarGroupProps {
  /**
   * Avatars, in the order the app ranks them, all with the same `size`.
   */
  children: Snippet
  /**
   * Maximum number drawn; the rest become "+N", and omitting it draws all.
   */
  max?: number
  /**
   * The group’s accessible name, such as "Assignees" rather than "Avatars".
   */
  label: string
}
</script>

<script lang="ts">
let { children, max, label: labelOwn }: AvatarGroupProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const childrenScope: SlotScope = new SlotScope({
  pass: (child): Record<string, unknown> => ({ label: child.label ?? child.name }),
  take: () => max,
})
childrenScope.probe(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.group} role="group" aria-label={label}
    ><SlotOutlet scope={childrenScope} snippet={children}
    />{#if max !== undefined && childrenScope.read().count > max
      }<span
        class={[styles.avatar, styles.surplus]}
        data-size={childrenScope.read().props.size ?? 'md'}
        >{`+${childrenScope.read().count - max}`
      }</span
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
